/* v6 · 修复 App 内更新连不上 GitHub Release 资产。
   现象：点「立即更新」报 "Failed to connect to release-assets.githubusercontent.com/127.0.0.1:443"。
   根因：latest.json 的下载地址指向 GitHub Release，其资产域在国内常被解析到 127.0.0.1，
        Updater.java 的 HttpURLConnection 直连必然失败，错误原文被回贴到下载卡片上。
   修复：所有更新入口统一改用系统浏览器打开新的 123 云盘分享页；openDownloadPage
        会复制提取码 f3sa 并拉起浏览器，不再发起应用内下载，故不可能再出现该报错。
   兼容：window 捕获阶段抢在历史 v5 补丁（document 捕获、指向 GitHub v5.20）之前；
        同时覆盖全局函数，应对 app.js 自带 window 捕获监听器的调用。 */
(function (w, d) {
  var URL = "https://1855215134.share.123pan.cn/123pan/lmaCvd-nid8h?pwd=f3sa#";
  var PW  = "f3sa";
  var last = 0;
  function open() {
    var now = Date.now();
    if (now - last < 800) return;            /* 一次点击只打开一次 */
    last = now;
    var N = w.ZhikeNative;
    if (N && typeof N.openDownloadPage === "function") {
      try { N.openDownloadPage(URL, PW); return; } catch (e) {}
    }
    if (N && typeof N.openUrl === "function") {
      try { N.openUrl(URL); return; } catch (e) {}
    }
    try { w.open(URL, "_blank", "noopener,noreferrer"); } catch (e) {}
  }
  /* app.js 的 window 捕获监听器与强制升级按钮最终都会调用这些全局函数 */
  w.checkUpdate        = open;
  w.startApkUpdate     = open;
  w.openDownloadLegacy = open;
  w.showUpdSheet       = open;
  /* 老版本没有 app.js 的 window 监听器；这条监听器同时压制历史 v5 补丁的改道 */
  if (!w.__zkUpdHotV6) {
    w.__zkUpdHotV6 = 1;
    w.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      if (t.closest("#zk-upgrade, #btn-check-update, [data-zk='check-update']")) {
        e.preventDefault();
        e.stopImmediatePropagation();
        open();
      }
    }, true);
  }
})(window, document);
